import { ChangeDetectionStrategy, Component, inject, output, signal } from '@angular/core';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { SchoolService } from '@org/api-services';
import { messageForError } from '@org/interceptors';
import { SchoolFields } from '@org/shared-models';
import { CardComponent, CloseButtonComponent } from '@org/ui';
import { SchoolFormComponent } from './school-form';

/**
 * The form for a new school, shown in the panel beside the list (platform U10, school spec R2-R5, R7). The code is
 * generated by the server (R15). It reports the created school's id; the page opens it.
 */
@Component({
  selector: 'app-school-add',
  standalone: true,
  imports: [TranslatePipe, CardComponent, CloseButtonComponent, SchoolFormComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="flex flex-col gap-5">
      <div class="flex items-center gap-3">
        <h1 class="mr-auto text-xl font-semibold text-primary-fg">{{ 'school.add.title' | translate }}</h1>
        <app-close-button [label]="'school.close' | translate" (clicked)="closed.emit()" />
      </div>
      <app-card>
        <app-school-form [saving]="saving()" [error]="error()" submitLabel="school.add.submit" (submitted)="add($event)" (cancelled)="closed.emit()" />
      </app-card>
    </div>
  `,
})
export class SchoolAddComponent {
  private readonly schools = inject(SchoolService);
  private readonly translate = inject(TranslateService);

  readonly created = output<string>();
  readonly closed = output<void>();

  readonly saving = signal(false);
  readonly error = signal('');

  add(fields: SchoolFields): void {
    this.saving.set(true);
    this.error.set('');
    this.schools.create(fields).subscribe({
      next: (school) => {
        this.saving.set(false);
        this.created.emit(school.id);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.error.set(messageForError(error, this.translate));
      },
    });
  }
}
